// Prepare Search
// Checks your Settings and the form, and builds the Google Maps search.
// NICHE_PACK below decides which problems count and how many points each is worth (edit with care).
// Generated by Client Finder Agent. You normally never need to edit this node: change the
// values in the "⚙️ Settings" node instead.

// ---- util.js ----

function str(v) {
  return v === undefined || v === null ? '' : String(v).trim();
}

function num(v, fallback = null) {
  if (v === '' || v === null || v === undefined || typeof v === 'boolean') return fallback;
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

function int(v, fallback = 0) {
  const n = num(v, null);
  return n === null ? fallback : Math.trunc(n);
}

function clamp(n, lo, hi) {
  return Math.min(hi, Math.max(lo, n));
}

// ---- places.js ----

const FORM_FIELDS = {
  businessType: 'Business type',
  location: 'City or area',
  maxLeads: 'How many businesses?',
};

const MAX_LEADS_LIMIT = 60;

function firstValue(...values) {
  for (const v of values) {
    const s = str(v);
    if (s) return s;
  }
  return '';
}

// input = form submission (labels as keys) merged with the Settings node values.
function buildSearch(input) {
  const businessType = firstValue(input[FORM_FIELDS.businessType], input.businessType);
  const location = firstValue(input[FORM_FIELDS.location], input.location);
  if (!businessType || !location) {
    throw new Error('Please fill in both "Business type" and "City or area" (for example: "dentists" and "Austin, TX").');
  }
  const requested = int(firstValue(input[FORM_FIELDS.maxLeads], input.maxLeads), 0);
  const maxLeads = clamp(requested > 0 ? requested : 40, 1, MAX_LEADS_LIMIT);
  const textQuery = `${businessType} in ${location}`;
  const body = { textQuery, pageSize: Math.min(20, maxLeads) };
  const languageCode = str(input.searchLanguage).toLowerCase();
  if (/^[a-z]{2}(-[a-z]{2})?$/.test(languageCode)) body.languageCode = languageCode;
  const regionCode = str(input.searchCountryCode).toUpperCase();
  if (/^[A-Z]{2}$/.test(regionCode)) body.regionCode = regionCode;
  return {
    businessType,
    location,
    textQuery,
    maxLeads,
    maxPages: Math.ceil(maxLeads / 20),
    requestBody: body,
  };
}

// ---- steps.js ----

const SETTING_KEYS = [
  'yourName',
  'yourBusinessName',
  'yourWebsite',
  'yourPhone',
  'yourAddress',
  'yourService',
  'yourOffer',
  'emailLanguage',
  'emailTone',
  'maxEmailWords',
  'optOutLine',
  'googleSheetUrl',
  'createGmailDrafts',
  'minScoreToPitch',
  'aiModel',
  'aiEffort',
  'searchLanguage',
  'searchCountryCode',
  'followUpDays',
  'maxFollowUps',
];

function stop(title, message, fatal) {
  return { stop: true, fatal: Boolean(fatal), title, message };
}

function isSheetUrl(url) {
  return /^https:\/\/docs\.google\.com\/spreadsheets\/d\/[a-zA-Z0-9_-]{20,}/.test(str(url));
}

function pickSettings(input, pack) {
  const s = {};
  for (const k of SETTING_KEYS) if (input[k] !== undefined) s[k] = input[k];
  if (pack) {
    if (!str(s.yourService)) s.yourService = pack.defaultService;
    if (!str(s.yourOffer)) s.yourOffer = pack.defaultOffer;
  }
  return s;
}

// "Prepare Search": validates the form + Settings and builds the job every later step reads.
function stepPrepareJob(input, pack, options) {
  const opts = options || {};
  const now = opts.now || new Date();
  const settings = pickSettings(input || {}, pack);
  if (opts.requireSheet && (!str(settings.yourName) || /^your name$/i.test(str(settings.yourName)))) {
    return stop('One setup step left', 'Open the "⚙️ Settings" node in n8n and replace "Your Name" (yourName) with your real name, plus your business, service and offer. They are used to sign every pitch.');
  }
  if (opts.requireSheet && !isSheetUrl(settings.googleSheetUrl)) {
    return stop(
      'One setup step left',
      'Open the "⚙️ Settings" node in n8n and paste the full URL of your Client Finder Google Sheet into googleSheetUrl (it starts with https://docs.google.com/spreadsheets/d/). Then submit this form again.',
    );
  }
  let search;
  try {
    search = buildSearch(Object.assign({}, input, settings));
  } catch (e) {
    return stop('Missing search details', e.message);
  }
  return {
    stop: false,
    startedAt: now.toISOString(),
    search,
    settings,
    pack: pack || null,
    nicheTitle: pack ? pack.title : 'Lite',
  };
}

// ---- this step ----
const NICHE_PACK = {
  "id": "reviews",
  "title": "Google Reviews & Reputation",
  "tagline": "Find businesses with a low rating or far fewer reviews than their competitors.",
  "needsWebsiteCheck": true,
  "needsPageSpeed": false,
  "defaultService": "getting more 5-star Google reviews from happy customers",
  "defaultOffer": "a free one-page plan to get more reviews from customers they already have",
  "exampleSearch": {
    "businessType": "hair salons",
    "location": "Manchester, UK"
  },
  "weights": {
    "low_rating": 45,
    "few_reviews": 45,
    "no_website": 10
  },
  "thresholds": {},
  "pitchAngle": "The sender helps businesses collect more Google reviews. Compare the business to its local competitors using only the numbers provided, and frame more reviews as winning the comparison customers make on Google Maps. Never promise a specific rating or number of reviews.",
  "fallback": {
    "subject": "your Google reviews",
    "impact": "Reviews are usually the first thing people compare on Google Maps, so a steady flow of fresh reviews can change who they call."
  }
};
return [{ json: stepPrepareJob($input.first().json, NICHE_PACK, { requireSheet: true }) }];

// Clean Leads
// Turns the Google Maps pages into one item per open business (no duplicates).
// Generated by Client Finder Agent. You normally never need to edit this node: change the
// values in the "⚙️ Settings" node instead.

// ---- util.js ----

function str(v) {
  return v === undefined || v === null ? '' : String(v).trim();
}

function num(v, fallback = null) {
  if (v === '' || v === null || v === undefined || typeof v === 'boolean') return fallback;
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

function int(v, fallback = 0) {
  const n = num(v, null);
  return n === null ? fallback : Math.trunc(n);
}

function clamp(n, lo, hi) {
  return Math.min(hi, Math.max(lo, n));
}

function round(n, digits = 0) {
  const f = 10 ** digits;
  return Math.round(n * f) / f;
}

function median(values) {
  const a = values.filter((x) => typeof x === 'number' && Number.isFinite(x)).sort((x, y) => x - y);
  if (!a.length) return null;
  const mid = Math.floor(a.length / 2);
  return a.length % 2 ? a[mid] : (a[mid - 1] + a[mid]) / 2;
}

const URL_RE = /^(https?):\/\/(?:[^/?#@]*@)?([^/?#:\s]+)(?::(\d{1,5}))?([^?#]*)(\?[^#]*)?(#.*)?$/i;

// Minimal URL parser (n8n's Code sandbox has no URL class). Returns null for anything that is not http(s).
function parseUrl(value) {
  const m = str(value).match(URL_RE);
  if (!m) return null;
  const hostname = m[2].toLowerCase().replace(/\.$/, '');
  if (!hostname.includes('.') || hostname.startsWith('.') || hostname.includes('..')) return null;
  return {
    protocol: m[1].toLowerCase() + ':',
    hostname,
    port: m[3] || '',
    pathname: m[4] ? (m[4].startsWith('/') ? m[4] : '/' + m[4]) : '/',
    search: m[5] && m[5] !== '?' ? m[5] : '',
    hash: m[6] || '',
  };
}

function formatUrl(u) {
  return `${u.protocol}//${u.hostname}${u.port ? ':' + u.port : ''}${u.pathname.replace(/ /g, '%20')}${u.search.replace(/ /g, '%20')}`;
}

// Returns a canonical absolute http(s) URL, or '' when the value is not a usable web address.
function normalizeUrl(value) {
  let s = str(value);
  if (!s) return '';
  if (/^\/\//.test(s)) s = 'http:' + s;
  if (!/^https?:\/\//i.test(s)) {
    if (/^[a-z][a-z0-9+.-]*:/i.test(s)) return '';
    s = 'http://' + s;
  }
  const u = parseUrl(s);
  return u ? formatUrl(u) : '';
}

function hostOf(url) {
  const u = parseUrl(url);
  return u ? u.hostname.replace(/^www\./, '') : '';
}

// ---- places.js ----

const MAX_LEADS_LIMIT = 60;

// HTTP status from a Google error body ({code: 403}) or an n8n error item ({status: 403, statusCode: 403, httpCode: '403'}).
function httpStatusOf(err) {
  const e = err || {};
  for (const v of [e.httpCode, e.statusCode, e.status, e.code, e.response && e.response.status]) {
    const n = int(v, 0);
    if (n >= 100 && n < 600 && /^\d+$/.test(String(v).trim())) return n;
  }
  const m = str(e.message).match(/^(\d{3})\b/);
  return m ? Number(m[1]) : 0;
}

// Collects every string inside an error payload. n8n stores API errors in different shapes
// ({message: '403 - "{...}"'}, {error: '{"error":{...}}', statusCode}, {description}), so checks run on all of it.
function errorText(err) {
  const parts = [];
  const walk = (v, depth) => {
    if (v === null || v === undefined || depth > 4) return;
    if (typeof v === 'string') {
      parts.push(v.replace(/\\"/g, '"'));
      return;
    }
    if (typeof v !== 'object') return;
    for (const k of ['message', 'description', 'error', 'status', 'statusText', 'body', 'details']) if (k in v) walk(v[k], depth + 1);
  };
  walk(err, 0);
  return parts.join(' | ');
}

// The most useful single message inside an error payload (the API's own message when present).
function errorSummary(err) {
  const text = errorText(err);
  const m = text.match(/"message"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  if (m) return m[1];
  const e = err || {};
  return str(typeof e === 'string' ? e : e.message || e.description || text).slice(0, 300);
}

// Turns a Google / n8n error payload into a message a non-developer can act on.
function explainGoogleError(page, apiName) {
  const err = page && page.error;
  if (!err) return '';
  const message = errorSummary(err);
  const code = httpStatusOf(err);
  const text = `${errorText(err)} ${code}`;
  const api = apiName || 'Google';
  if (/API key not valid|API_KEY_INVALID|invalid api key/i.test(text)) {
    return `${api}: your Google API key was rejected. Open the "Google API Key" credential in n8n and paste the key again (Header Name must be X-Goog-Api-Key).`;
  }
  if (/has not been used|is disabled|SERVICE_DISABLED|not been enabled|API not enabled/i.test(text)) {
    return `${api}: this API is not enabled in your Google Cloud project yet. Follow step 2 of the setup guide to enable it, wait 2 minutes, then run again.`;
  }
  if (/billing/i.test(text)) {
    return `${api}: Google requires a billing account on your Cloud project (the free monthly allowance still applies). See step 2 of the setup guide.`;
  }
  if (/referer|referrer|API_KEY_HTTP_REFERRER_BLOCKED|IP address|API_KEY_IP_ADDRESS_BLOCKED|blocked/i.test(text)) {
    return `${api}: your API key has an application restriction that blocks n8n. In Google Cloud > Credentials, set "Application restrictions" to None and restrict the key by API instead.`;
  }
  if (code === 429 || /quota|RESOURCE_EXHAUSTED|rate/i.test(text)) {
    return `${api}: Google says you hit a quota or rate limit. Wait a few minutes or raise the quota in Google Cloud.`;
  }
  if (code === 401 || code === 403 || /PERMISSION_DENIED|unauthori[sz]ed|forbidden/i.test(text)) {
    return `${api}: permission denied (${message || 'no details'}). Check that the API key is correct and the API is enabled.`;
  }
  return `${api} returned an error: ${message || JSON.stringify(err).slice(0, 300)}`;
}

// Google listings often link to a social profile or a booking page instead of a real website.
// Those businesses have no website of their own; we must not judge facebook.com's HTML as theirs.
const PLATFORM_HOSTS = [
  ['Facebook page', /(^|\.)(facebook\.com|fb\.com|fb\.me|m\.me)$/],
  ['Instagram profile', /(^|\.)(instagram\.com|instagr\.am)$/],
  ['TikTok profile', /(^|\.)tiktok\.com$/],
  ['X/Twitter profile', /(^|\.)(twitter\.com|x\.com)$/],
  ['YouTube channel', /(^|\.)(youtube\.com|youtu\.be)$/],
  ['LinkedIn page', /(^|\.)linkedin\.com$/],
  ['link-in-bio page', /(^|\.)(linktr\.ee|linkin\.bio|beacons\.ai|lnk\.bio|taplink\.cc|bio\.link)$/],
  ['WhatsApp link', /(^|\.)(wa\.me|whatsapp\.com)$/],
  ['Google Maps link', /(^|\.)(g\.page|goo\.gl|maps\.app\.goo\.gl|business\.site)$/],
  ['Yelp page', /(^|\.)yelp\.[a-z.]+$/],
  ['Tripadvisor page', /(^|\.)tripadvisor\.[a-z.]+$/],
  ['Justdial page', /(^|\.)justdial\.com$/],
  ['booking page', /(^|\.)(calendly\.com|booksy\.com|fresha\.com|vagaro\.com|setmore\.com|square\.site|squareup\.com|zocdoc\.com|practo\.com|opentable\.[a-z.]+|resy\.com|treatwell\.[a-z.]+|mindbodyonline\.com|schedulicity\.com|acuityscheduling\.com)$/],
];

function websitePlatform(url) {
  const host = hostOf(url);
  if (!host) return '';
  for (const [name, re] of PLATFORM_HOSTS) if (re.test(host)) return name;
  return '';
}

const DAY_NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

// Summarises Google's regularOpeningHours into the facts the "limited hours" check needs.
function summarizeHours(hours) {
  if (!hours || !Array.isArray(hours.periods) || !hours.periods.length) return { known: false };
  const periods = hours.periods.filter((p) => p && p.open && Number.isInteger(p.open.day));
  if (!periods.length) return { known: false };
  const first = periods[0];
  if (periods.length === 1 && !first.close && int(first.open.hour, 0) === 0 && int(first.open.minute, 0) === 0) {
    return { known: true, open24h: true, closedDays: [], earlyCloseWeekdays: 0, latestClose: {} };
  }
  const latestClose = {};
  for (const p of periods) {
    const day = p.open.day;
    let closeHour = 24;
    if (p.close && Number.isInteger(p.close.day)) {
      closeHour = int(p.close.hour, 0) + int(p.close.minute, 0) / 60;
      if (p.close.day !== day) closeHour += 24; // closes after midnight
    }
    latestClose[day] = Math.max(latestClose[day] || 0, closeHour);
  }
  const closedDays = [];
  for (let d = 0; d < 7; d++) if (latestClose[d] === undefined) closedDays.push(DAY_NAMES[d]);
  let earlyCloseWeekdays = 0;
  for (let d = 1; d <= 5; d++) if (latestClose[d] !== undefined && latestClose[d] < 18) earlyCloseWeekdays++;
  return {
    known: true,
    open24h: false,
    closedDays,
    earlyCloseWeekdays,
    latestClose,
    weekdayText: Array.isArray(hours.weekdayDescriptions) ? hours.weekdayDescriptions.map(str) : [],
  };
}

// pages = every response body returned by the paginated Text Search request.
function normalizePlaces(pages, options) {
  const opts = options || {};
  const maxLeads = clamp(int(opts.maxLeads, 40) || 40, 1, MAX_LEADS_LIMIT);
  const list = Array.isArray(pages) ? pages : [];
  const errors = list.filter((p) => p && p.error).map((p) => explainGoogleError(p, 'Google Places API'));
  const leads = [];
  const seen = new Set();
  let skippedClosed = 0;
  let duplicates = 0;
  for (const page of list) {
    if (!page || !Array.isArray(page.places)) continue;
    for (const p of page.places) {
      if (leads.length >= maxLeads) break;
      const placeId = str(p && p.id);
      if (!placeId) continue;
      if (seen.has(placeId)) {
        duplicates++;
        continue;
      }
      seen.add(placeId);
      const status = str(p.businessStatus);
      if (status && status !== 'OPERATIONAL') {
        skippedClosed++;
        continue;
      }
      leads.push({
        placeId,
        name: str(p.displayName && p.displayName.text) || '(name not listed)',
        category: str(p.primaryTypeDisplayName && p.primaryTypeDisplayName.text),
        address: str(p.formattedAddress),
        phone: str(p.nationalPhoneNumber || p.internationalPhoneNumber),
        internationalPhone: str(p.internationalPhoneNumber),
        website: normalizeUrl(p.websiteUri),
        websitePlatform: websitePlatform(normalizeUrl(p.websiteUri)),
        mapsUrl: str(p.googleMapsUri),
        rating: num(p.rating),
        reviewCount: int(p.userRatingCount, 0),
        hours: summarizeHours(p.regularOpeningHours),
      });
    }
  }
  if (!leads.length && errors.length) throw new Error(errors[0]);
  return { leads, skippedClosed, duplicates, errors };
}

function marketStats(leads) {
  const rated = leads.filter((l) => l.rating !== null && l.reviewCount >= 5);
  const reviewCounts = leads.map((l) => l.reviewCount).filter((n) => Number.isFinite(n));
  const top = [...reviewCounts].sort((a, b) => b - a).slice(0, 3);
  const med = median(reviewCounts);
  const medRating = median(rated.map((l) => l.rating));
  return {
    count: leads.length,
    medianReviews: med === null ? null : Math.round(med),
    medianRating: medRating === null ? null : round(medRating, 1),
    topReviewsAvg: top.length ? Math.round(top.reduce((a, b) => a + b, 0) / top.length) : null,
  };
}

// ---- steps.js ----

function stop(title, message, fatal) {
  return { stop: true, fatal: Boolean(fatal), title, message };
}

// "Clean Leads": flattens the paginated Places responses into one item per business.
function stepCleanLeads(pages, job) {
  let result;
  try {
    result = normalizePlaces(pages, { maxLeads: job.search.maxLeads });
  } catch (e) {
    return [stop('Google Maps search failed', e.message)];
  }
  if (!result.leads.length) {
    return [stop('No businesses found', `Google Maps returned no open businesses for "${job.search.textQuery}". Try a broader area (a city instead of a neighbourhood) or a different business type.`)];
  }
  const market = marketStats(result.leads);
  return result.leads.map((lead) => Object.assign({}, lead, { market }));
}

// ---- this step ----
const job = $('Prepare Search').first().json;
const pages = $input.all().map((i) => i.json);
return stepCleanLeads(pages, job).map((json) => ({ json }));

// Skip Saved Leads
// Removes businesses that are already in your sheet, so nobody gets pitched twice.
// Generated by Client Finder Agent. You normally never need to edit this node: change the
// values in the "⚙️ Settings" node instead.

// ---- util.js ----

function str(v) {
  return v === undefined || v === null ? '' : String(v).trim();
}

function plural(n, word, pluralWord) {
  return `${n} ${n === 1 ? word : pluralWord || word + 's'}`;
}

// ---- places.js ----

// Collects every string inside an error payload. n8n stores API errors in different shapes
// ({message: '403 - "{...}"'}, {error: '{"error":{...}}', statusCode}, {description}), so checks run on all of it.
function errorText(err) {
  const parts = [];
  const walk = (v, depth) => {
    if (v === null || v === undefined || depth > 4) return;
    if (typeof v === 'string') {
      parts.push(v.replace(/\\"/g, '"'));
      return;
    }
    if (typeof v !== 'object') return;
    for (const k of ['message', 'description', 'error', 'status', 'statusText', 'body', 'details']) if (k in v) walk(v[k], depth + 1);
  };
  walk(err, 0);
  return parts.join(' | ');
}

// The most useful single message inside an error payload (the API's own message when present).
function errorSummary(err) {
  const text = errorText(err);
  const m = text.match(/"message"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  if (m) return m[1];
  const e = err || {};
  return str(typeof e === 'string' ? e : e.message || e.description || text).slice(0, 300);
}

// ---- sheet.js ----

function existingPlaceIds(rows) {
  const ids = new Set();
  for (const r of rows || []) {
    const id = str(r && r['Place ID']);
    if (id) ids.add(id);
  }
  return ids;
}

// ---- steps.js ----

function stop(title, message, fatal) {
  return { stop: true, fatal: Boolean(fatal), title, message };
}

// "Skip Saved Leads": drops businesses already in the sheet so nobody gets pitched twice.
function stepSkipSaved(leads, savedRows, job) {
  const stopped = (leads || []).find((l) => l && l.stop);
  if (stopped) return [stopped]; // an earlier step already explained what went wrong
  const rows = (savedRows || []).filter((r) => r && Object.keys(r).length);
  const sheetError = rows.find((r) => r.error);
  if (sheetError) {
    const msg = errorSummary(sheetError.error);
    let hint = 'Check that googleSheetUrl in Settings is correct, the sheet has a tab named "Leads", and the Google Sheets credential belongs to the Google account that owns the sheet.';
    if (/not found|404|Unable to parse range|Leads/i.test(msg)) hint = 'n8n could not find the "Leads" tab. Import the Client Finder CRM template into Google Sheets (it already has the tab and columns) and paste that sheet\'s URL into Settings.';
    return [stop("Couldn't open your Google Sheet", `${msg.slice(0, 200)} — ${hint}`)];
  }
  const leadList = (leads || []).filter((l) => l && !l.stop);
  const saved = existingPlaceIds(rows);
  const fresh = leadList.filter((l) => !saved.has(l.placeId));
  if (!fresh.length) {
    return [stop('Nothing new this time', `All ${plural(leadList.length, 'business', 'businesses')} found for "${job.search.textQuery}" are already in your sheet. Try a nearby area or a related business type.`)];
  }
  return fresh;
}

// ---- this step ----
const job = $('Prepare Search').first().json;
const leads = $('Clean Leads').all().map((i) => i.json);
const saved = $input.all().map((i) => i.json);
return stepSkipSaved(leads, saved, job).map((json) => ({ json }));

// Check Website
// Reads each homepage: did it load, contact email, booking/chat tools, social links, copyright year...
// Generated by Client Finder Agent. You normally never need to edit this node: change the
// values in the "⚙️ Settings" node instead.

// ---- util.js ----

function str(v) {
  return v === undefined || v === null ? '' : String(v).trim();
}

function num(v, fallback = null) {
  if (v === '' || v === null || v === undefined || typeof v === 'boolean') return fallback;
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

function int(v, fallback = 0) {
  const n = num(v, null);
  return n === null ? fallback : Math.trunc(n);
}

